// index is a file nothing loads.
const CLAUDE_INDEX_IMPORT_RE = new RegExp(`^\\s*${CLAUDE_INDEX_IMPORT.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*$`, 'm');

