+  // The same routing table the prose injector rendered, for every pack DISCOVERED
+  // rather than only the active ones: the discovered set is the set a session can
+  // route content INTO. Rows are capped at 20 words a side by the manifest schema,
+  // so the table stays a cheap thing to carry.
+  const routed = packs.filter((p) => p.ruleRoutingGuidance?.belongs && p.ruleRoutingGuidance?.excludes);
