  writeFileSync(path, content);
  return true;
}

// CLI: `node generate-claude-index.mjs [--write] [root]` — print the index, or
// write it. The path a check or a session is told to run to regenerate by hand.
async function main() {
  const argv = process.argv.slice(2);
