  assert.ok(r.changed.some((c) => c.includes('claude.GENERATED.md')));
  assert.match(readFileSync(join(root, '.claudinite', 'claude.GENERATED.md'), 'utf8'), /@shared\/packs\/tidy-repo\/RULES\.md/);
});

