import { join } from 'node:path';
import { finding } from '../../engine/checks/helpers/findings.mjs';
import {
  rulesIndexContent, RULES_INDEX_FILE, RULES_INDEX_IMPORT,
} from '../../engine/pack_loader/generate-rules-index.mjs';

// The rules index is the ONLY channel a pack's prose reaches a session on (#807): the
// SessionStart prose step that used to carry it is gone, deliberately, so that no
// session can be running on a stale copy of one channel while the other is fine.
//
// That single channel is what makes this check load-bearing rather than tidy. Every
// converge writes the index, but a repo whose converge has stopped, whose CLAUDE.md was
// hand-edited, or that declared a pack since its last refresh, now has NO pack rules at
// all — and the failure is invisible from inside the session, which is the exact
// property #807 was filed about. So the repo goes red until it is fixed, which is the
// only signal available: an agent cannot notice rules it never received.
//
// BLOCKING, and not by habit. An advisory here would be read past by the very session
// that is missing the rules that would have told it not to.
//
// Both halves are checked because either alone is silent. An index that no CLAUDE.md
// imports loads for nobody; an import pointing at a stale index loads last week's
// declaration. And the import must be matched OUTSIDE code spans — the harness skips
// `@` mentions in backticks, so a CLAUDE.md that merely documents the line is one it
// never follows.
const rule = {
  id: 'rules-index-current',
  severity: 'blocking',
  description: `${RULES_INDEX_FILE} must exist, match this repo's declaration, and be imported by CLAUDE.md`,
  doc: 'vendoring/DESIGN.md',
  why: 'it is the only channel a pack\'s rules reach a session on; stale or unimported means the session silently runs with none',

  async run(ctx) {
    const expected = await rulesIndexContent(ctx.root);
    // Nothing to import — no active pack has vendored prose. That is a mount that has
    // not converged yet, which the engine's own unknown-pack error already reports;
    // this rule has nothing to say about it.
    if (expected === null) return [];

    const findings = [];
    const actual = ctx.read(RULES_INDEX_FILE);
    if (actual === null) {
      findings.push(finding(rule, {
        file: RULES_INDEX_FILE,
        what: 'the rules index is missing, so no pack\'s RULES.md loads into a session',
        fix: `run \`node ${join(ctx.sharedMount ?? '.claudinite/shared', 'engine/pack_loader/generate-rules-index.mjs')} --write\` and commit the result`,
      }));
    } else if (actual !== expected) {
      findings.push(finding(rule, {
        file: RULES_INDEX_FILE,
        what: 'the rules index does not match this repo\'s declared packs, so a session loads the wrong set',
        fix: `run \`node ${join(ctx.sharedMount ?? '.claudinite/shared', 'engine/pack_loader/generate-rules-index.mjs')} --write\` and commit the result`,
      }));
    }

    const claudeMd = ctx.read('CLAUDE.md');
    const imported = claudeMd !== null && claudeMd.split('\n')
      .some((line) => !line.includes('`') && line.includes(RULES_INDEX_IMPORT));
    if (!imported) {
      findings.push(finding(rule, {
        file: 'CLAUDE.md',
        what: `CLAUDE.md does not import ${RULES_INDEX_FILE}, so nothing loads it`,
        fix: `add a line \`${RULES_INDEX_IMPORT}\` to CLAUDE.md — outside backticks, or the harness will not follow it`,
      }));
    }
    return findings;
  },
};

export default rule;

