      // seed that would red every member for a night.
      if (readFileSync(join(root, '.claudinite-checks.json'), 'utf8') !== declarationBefore) {
        steps.push(step('re-converge', [join(CANON, 'vendoring/apply-vendor-set.mjs'), '--target', root]));
